#include "shared/sea_nuclear_wave.hpp"
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdio>
using namespace std;
struct Cluster{float x,z,t,weight;};
SeaNuclearWaveSample eval(const vector<SeaNuclearWave>&w,const vector<float>&weights,float x,float z){SeaNuclearWaveSample r;for(size_t i=0;i<w.size();i++){auto q=EvaluateSeaNuclearWave(w[i],x,z);r.height+=q.height*weights[i];r.slopeX+=q.slopeX*weights[i];r.slopeZ+=q.slopeZ*weights[i];r.foam=max(r.foam,q.foam);r.load=max(r.load,q.load);}CompressSeaNuclearWaveSample(r);return r;}
int main(){constexpr int count=3300;constexpr float now=count*.016f;vector<SeaNuclearWave>exact;vector<float>ones;for(int i=1;i<=count;i++){SeaNuclearWave w{float((i*197)%3000-1500),float((i*311)%3000-1500),0,0,true,1};w.Advance(now-i*.016f);if(w.active){exact.push_back(w);ones.push_back(1);}}for(auto limit:vector<pair<float,float>>{{128,.5},{200,2},{400,4}}){vector<Cluster> c;for(int i=1;i<=count;i++){float x=(i*197)%3000-1500,z=(i*311)%3000-1500,t=i*.016f;Cluster *best=nullptr;float score=1e30;for(auto&v:c){float dx=x-v.x,dz=z-v.z,dt=t-v.t;if(dt<0||dt>limit.second||dx*dx+dz*dz>limit.first*limit.first)continue;float s=dx*dx+dz*dz+dt*dt*4900;if(s<score){score=s;best=&v;}}if(!best)c.push_back({x,z,t,1});else{float n=best->weight+1;best->x+=(x-best->x)/n;best->z+=(z-best->z)/n;best->t+=(t-best->t)/n;best->weight=n;}}vector<SeaNuclearWave>packed;vector<float>weights;for(auto&g:c){SeaNuclearWave w{g.x,g.z,0,0,true,1};w.Advance(now-g.t);if(w.active){packed.push_back(w);weights.push_back(g.weight);}}double hs=0,ss=0,raw=0;float hm=0,sm=0,fm=0;int miss=0,N=3000;for(int i=0;i<N;i++){float x=-1600+fmodf(i*197.53f,3200),z=-1600+fmodf(i*319.41f,3200);auto a=eval(exact,ones,x,z),b=eval(packed,weights,x,z);float he=abs(a.height-b.height),se=hypotf(a.slopeX-b.slopeX,a.slopeZ-b.slopeZ);hs+=he*he;ss+=se*se;raw+=a.height*a.height;hm=max(hm,he);sm=max(sm,se);fm=max(fm,abs(a.foam-b.foam));miss+=(abs(a.height)>.1&&abs(b.height)<.01);}printf("radius=%.0f age=%.1f exact=%zu clusters=%zu height_rmse=%.3f signal_rms=%.3f height_max=%.3f slope_rmse=%.4f slope_max=%.4f foam_max=%.3f missed_10cm=%d/%d\n",limit.first,limit.second,exact.size(),packed.size(),sqrt(hs/N),sqrt(raw/N),hm,sqrt(ss/N),sm,fm,miss,N);}}
